class TermuxOrchestrator {
  private client: AxiosInstance
  private config: TermuxConfig
  private rateLimit?: RateLimit

  constructor(config: TermuxConfig) {
    this.config = {
      timeout: 30000,
      retryAttempts: 3,
      retryDelay: 1000,
      ...config
    }

    this.client = axios.create({
      baseURL: this.config.baseURL,
      timeout: this.config.timeout,
      headers: {
        'Content-Type': 'application/json',
        'User-Agent': 'OASIS-v3-Frontend/1.0.0',
        ...(this.config.apiKey && { Authorization: `Bearer ${this.config.apiKey}` })
      }
    })

    this.setupInterceptors()
  }

  private setupInterceptors() {
    // Request interceptor
    this.client.interceptors.request.use(
      (config) => {
        // Add timestamp to requests
        config.metadata = { startTime: Date.now() }
        return config
      },
      (error) => Promise.reject(error)
    )

    // Response interceptor
    this.client.interceptors.response.use(
      (response) => {
        // Extract rate limit info
        this.extractRateLimit(response)

        // Log request timing
        const duration = Date.now() - (response.config.metadata?.startTime || 0)
        console.debug(`API Request: ${response.config.method?.toUpperCase()} ${response.config.url} - ${duration}ms`)

        return response
      },
      async (error) => {
        const { config, response } = error

        // Handle rate limiting
        if (response?.status === 429) {
          const retryAfter = parseInt(response.headers['retry-after'] || '1')
          if (config && !config._retry && retryAfter <= 60) {
            config._retry = true
            await this.delay(retryAfter * 1000)
            return this.client(config)
          }
        }

        // Handle network errors with retry
        if (!response && config && this.shouldRetry(config)) {
          return this.retryRequest(config)
        }

        return Promise.reject(this.formatError(error))
      }
    )
  }

  private extractRateLimit(response: AxiosResponse) {
    const headers = response.headers
    if (headers['x-ratelimit-limit']) {
      this.rateLimit = {
        limit: parseInt(headers['x-ratelimit-limit']),
        remaining: parseInt(headers['x-ratelimit-remaining'] || '0'),
        reset: parseInt(headers['x-ratelimit-reset'] || '0'),
        retryAfter: headers['retry-after'] ? parseInt(headers['retry-after']) : undefined
      }
    }
  }

  private shouldRetry(config: any): boolean {
    const retryCount = config._retryCount || 0
    return retryCount < (this.config.retryAttempts || 3)
  }

  private async retryRequest(config: any) {
    config._retryCount = (config._retryCount || 0) + 1
    const delay = (this.config.retryDelay || 1000) * Math.pow(2, config._retryCount - 1)

    await this.delay(delay)
    return this.client(config)
  }

  private delay(ms: number): Promise<void> {
