websocket_hook = '''import { useEffect, useState, useRef, useCallback } from 'react'
import io, { Socket } from 'socket.io-client'
import { WebSocketMessage } from '@/types/api'
import toast from 'react-hot-toast'

interface WebSocketConfig {
  url?: string
  autoConnect?: boolean
  reconnectAttempts?: number
  reconnectDelay?: number
  enableHeartbeat?: boolean
  heartbeatInterval?: number
}

interface UseWebSocketReturn {
  socket: Socket | null
  isConnected: boolean
  isConnecting: boolean
  error: string | null
  data: any
  lastMessage: WebSocketMessage | null
  connect: () => void
  disconnect: () => void
  emit: (event: string, data: any) => void
  subscribe: (event: string, callback: (data: any) => void) => () => void
}

const defaultConfig: WebSocketConfig = {
  url: process.env.NEXT_PUBLIC_WS_URL || 'ws://localhost:8000',
  autoConnect: true,
  reconnectAttempts: 5,
  reconnectDelay: 1000,
  enableHeartbeat: true,
  heartbeatInterval: 30000
}

export function useWebSocket(config: WebSocketConfig = {}): UseWebSocketReturn {
  const finalConfig = { ...defaultConfig, ...config }

  const [socket, setSocket] = useState<Socket | null>(null)
  const [isConnected, setIsConnected] = useState(false)
  const [isConnecting, setIsConnecting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [data, setData] = useState<any>(null)
  const [lastMessage, setLastMessage] = useState<WebSocketMessage | null>(null)

  const reconnectAttempts = useRef(0)
  const heartbeatInterval = useRef<NodeJS.Timeout | null>(null)
  const subscribers = useRef<Map<string, Set<(data: any) => void>>>(new Map())

  const startHeartbeat = useCallback(() => {
    if (!finalConfig.enableHeartbeat || !socket) return

    heartbeatInterval.current = setInterval(() => {
      if (socket.connected) {
        socket.emit('heartbeat', { timestamp: Date.now() })
      }
    }, finalConfig.heartbeatInterval)
  }, [socket, finalConfig.enableHeartbeat, finalConfig.heartbeatInterval])

  const stopHeartbeat = useCallback(() => {
    if (heartbeatInterval.current) {
      clearInterval(heartbeatInterval.current)
      heartbeatInterval.current = null
    }
  }, [])

  const connect = useCallback(() => {
    if (socket?.connected) return

    setIsConnecting(true)
    setError(null)

    const newSocket = io(finalConfig.url!, {
      transports: ['websocket', 'polling'],
      timeout: 20000,
      auth: {
        token: process.env.NEXT_PUBLIC_TERMUX_API_KEY
      }
    })

    // Connection events
    newSocket.on('connect', () => {
      console.log('WebSocket connected')
      setIsConnected(true)
      setIsConnecting(false)
      setError(null)
      reconnectAttempts.current = 0
      startHeartbeat()
      toast.success('Connected to real-time updates', { id: 'ws-connection' })
    })

    newSocket.on('disconnect', (reason) => {
      console.log('WebSocket disconnected:', reason)
      setIsConnected(false)
      stopHeartbeat()

      if (reason === 'io server disconnect') {
        // Server initiated disconnect, try to reconnect
        handleReconnect(newSocket)
      } else if (reason === 'transport close' || reason === 'ping timeout') {
        // Network issues, try to reconnect
        handleReconnect(newSocket)
      }
    })

    newSocket.on('connect_error', (error) => {
      console.error('WebSocket connection error:', error)
      setError(error.message)
      setIsConnecting(false)
      handleReconnect(newSocket)
    })

    // Message handling
    newSocket.on('message', (message: WebSocketMessage) => {
      setLastMessage(message)
      setData(message.data)

      // Notify subscribers
      const eventSubscribers = subscribers.current.get(message.type)
      if (eventSubscribers) {
        eventSubscribers.forEach(callback => callback(message.data))
      }

      // Handle specific message types
      switch (message.type) {
        case 'status_update':
          toast.info('System status updated')
          break
        case 'revenue_update':
          toast.success('Revenue updated')
          break
        case 'error':
          toast.error(`System error: ${message.data.message}`)
          break
        case 'new_request':
          // Handle new AI request notifications
          break
      }
    })

    // Specific event listeners
    newSocket.on('status_update', (data) => {
      setData(data)
      const eventSubscribers = subscribers.current.get('status_update')
      if (eventSubscribers) {
        eventSubscribers.forEach(callback => callback(data))
      }
    })

    newSocket.on('revenue_update', (data) => {
      const eventSubscribers = subscribers.current.get('revenue_update')
      if (eventSubscribers) {
        eventSubscribers.forEach(callback => callback(data))
      }
    })

    newSocket.on('ai_request', (data) => {
      const eventSubscribers = subscribers.current.get('ai_request')
      if (eventSubscribers) {
        eventSubscribers.forEach(callback => callback(data))
      }
    })

    newSocket.on('heartbeat_response', (data) => {
      // Handle heartbeat response if needed
      console.debug('Heartbeat response:', data)
    })

    setSocket(newSocket)
  }, [finalConfig.url, startHeartbeat, stopHeartbeat])

  const handleReconnect = useCallback((socketInstance: Socket) => {
    if (reconnectAttempts.current >= finalConfig.reconnectAttempts!) {
      setError('Failed to reconnect after multiple attempts')
      toast.error('Connection failed. Please refresh the page.', { id: 'ws-error' })
      return
    }

    reconnectAttempts.current++
    const delay = finalConfig.reconnectDelay! * Math.pow(2, reconnectAttempts.current - 1)

    setTimeout(() => {
      console.log(`Attempting to reconnect (${reconnectAttempts.current}/${finalConfig.reconnectAttempts})`)
      toast.loading('Reconnecting...', { id: 'ws-reconnect' })
      socketInstance.connect()
    }, delay)
  }, [finalConfig.reconnectAttempts, finalConfig.reconnectDelay])

  const disconnect = useCallback(() => {
    if (socket) {
      stopHeartbeat()
      socket.disconnect()
      setSocket(null)
      setIsConnected(false)
      setIsConnecting(false)
      toast.dismiss('ws-connection')
      toast.dismiss('ws-reconnect')
    }
  }, [socket, stopHeartbeat])

  const emit = useCallback((event: string, data: any) => {
    if (socket?.connected) {
      socket.emit(event, data)
    } else {
      console.warn('Cannot emit event: WebSocket not connected')
    }
  }, [socket])

  const subscribe = useCallback((event: string, callback: (data: any) => void) => {
    if (!subscribers.current.has(event)) {
      subscribers.current.set(event, new Set())
    }
    subscribers.current.get(event)!.add(callback)

    // Return unsubscribe function
    return () => {
      const eventSubscribers = subscribers.current.get(event)
      if (eventSubscribers) {
        eventSubscribers.delete(callback)
        if (eventSubscribers.size === 0) {
          subscribers.current.delete(event)
        }
      }
    }
  }, [])

  // Auto-connect on mount
  useEffect(() => {
    if (finalConfig.autoConnect) {
      connect()
    }

    return () => {
      disconnect()
    }
  }, [])

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      stopHeartbeat()
      if (socket) {
        socket.disconnect()
      }
    }
  }, [socket, stopHeartbeat])

  return {
    socket,
    isConnected,
    isConnecting,
    error,
    data,
    lastMessage,
    connect,
    disconnect,
    emit,
    subscribe
  }
}

// Utility hook for specific data subscriptions
export function useRealtimeData<T = any>(eventType: string, initialData?: T) {
  const [data, setData] = useState<T | undefined>(initialData)
  const { subscribe } = useWebSocket()

  useEffect(() => {
    const unsubscribe = subscribe(eventType, (newData: T) => {
      setData(newData)
    })

    return unsubscribe
  }, [eventType, subscribe])

  return data
}

// Hook for system status updates
export function useSystemStatus() {
  return useRealtimeData('status_update')
}

// Hook for revenue updates
export function useRevenueUpdates() {
  return useRealtimeData('revenue_update')
}

// Hook for AI request notifications
export function useAIRequestUpdates() {
  return useRealtimeData('ai_request')
}
