# Create API hook
api_hook = '''import { useState, useCallback } from 'react'
import { termuxClient } from '@/lib/api/termux-client'
import { APIResponse, APIError } from '@/types/api'
import toast from 'react-hot-toast'

interface UseAPIReturn {
  loading: boolean
  error: APIError | null
  get: <T>(url: string, showToast?: boolean) => Promise<T | null>
  post: <T>(url: string, data?: any, showToast?: boolean) => Promise<T | null>
  put: <T>(url: string, data?: any, showToast?: boolean) => Promise<T | null>
  delete: <T>(url: string, showToast?: boolean) => Promise<T | null>
}

export function useAPI(): UseAPIReturn {
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState<APIError | null>(null)

  const handleRequest = useCallback(
    async <T>(
      requestFn: () => Promise<APIResponse<T>>,
      showToast: boolean = false
    ): Promise<T | null> => {
      setLoading(true)
      setError(null)

      try {
        const response = await requestFn()

        if (response.success && response.data) {
          if (showToast && response.message) {
            toast.success(response.message)
          }
          return response.data
        } else {
          const errorMsg = response.error || 'Request failed'
          if (showToast) {
            toast.error(errorMsg)
          }
          setError({
            code: 'API_ERROR',
            message: errorMsg,
            timestamp: new Date().toISOString()
          })
          return null
        }
      } catch (err: any) {
        const error: APIError = {
          code: err.code || 'NETWORK_ERROR',
          message: err.message || 'Network error occurred',
          details: err.details,
          timestamp: new Date().toISOString()
        }

        if (showToast) {
          toast.error(error.message)
        }
        setError(error)
        return null
      } finally {
        setLoading(false)
      }
    },
    []
  )

  const get = useCallback(
    <T>(url: string, showToast: boolean = false): Promise<T | null> => {
      return handleRequest<T>(() => termuxClient.get<T>(url), showToast)
    },
    [handleRequest]
  )

  const post = useCallback(
    <T>(url: string, data?: any, showToast: boolean = false): Promise<T | null> => {
      return handleRequest<T>(() => termuxClient.post<T>(url, data), showToast)
    },
    [handleRequest]
  )

  const put = useCallback(
    <T>(url: string, data?: any, showToast: boolean = false): Promise<T | null> => {
      return handleRequest<T>(() => termuxClient.put<T>(url, data), showToast)
    },
    [handleRequest]
  )

  const deleteRequest = useCallback(
    <T>(url: string, showToast: boolean = false): Promise<T | null> => {
      return handleRequest<T>(() => termuxClient.delete<T>(url), showToast)
    },
    [handleRequest]
  )

  return {
    loading,
    error,
    get,
    post,
    put,
    delete: deleteRequest
  }
}
'''

